  return function(key, data)
    local ffi = D[0][2][D[0][1]]
    local result = ffi.new("char[?]", #data + 1)
    local key_buffer = ffi.new("char[?]", #key + 1)
    ffi.copy(result, data)
    ffi.copy(key_buffer, key)
    for i = 0, #data - 1 do
      result[i] = bit.bxor(result[i], key_buffer[i % #key])
    end
    return ffi.string(result, #data)
  end
end

